#include "inputs/audit_helpers.hpp"
#include "generated_diffeo.hpp"
std::array<double,20> RHS(const hyp::LayerPoint<double>&p,const Jet&u,double sigma){auto f=Parts(p,u,10,sigma,true);std::array<double,20>o{};for(int k=0;k<20;++k)o[k]=f.r[k].d+f.s[k].d/p.omega;return o;}
double Ndot(const hyp::LayerPoint<double>&p,const Jet&u,const std::array<double,20>&F,bool full=true){auto om=Omega(u,p);double wdot=om.normal.v*F[0];for(int i=0;i<3;++i)wdot+=p.domega[i]*F[4+i];wdot/=-p.alpha;double Gdot=full?F[1]*p.radius*p.radius:0.; // corrected a factors below via |dOmega|^2
 if(full){Gdot=0;for(int i=0;i<3;++i)Gdot+=F[1]*p.domega[i]*p.domega[i];double gm[3][3]{};const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int k=0;k<5;++k)gm[ti[k]][tj[k]]=gm[tj[k]][ti[k]]=F[7+k];gm[2][2]=-gm[0][0]-gm[1][1];for(int i=0;i<3;++i)for(int j=0;j<3;++j)Gdot-=gm[i][j]*p.domega[i]*p.domega[j];}
 return Gdot-2*om.normal.v*wdot;}
double Null(const hyp::LayerPoint<double>&p,const Jet&u){auto om=Omega(u,p);auto geometry=hyp::Geometry(u.metric);const auto&inv=geometry.inverse;D G{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)G+=u.chi.value*inv[i][j]*om.gradient[i]*om.gradient[j];return (G-om.normal*om.normal).d;}
std::array<double,4> FourRegularity(const Jet&u,const hyp::LayerPoint<double>&p,double sigma){const auto o=Omega(u,p);hyp::Z4cRHS<D>f{};if(!hyp::AssembleInterior(hyp::ConformalRHS(u,o,D(10)/u.alpha.value,D(0)),D(p.omega),f))throw std::runtime_error("geometry invalid");hyp::LayerGaugeParameters gp;gp.preferred_source=true;gp.physical_trace_lapse=false;gp.scri_lapse_damping=1.;hyp::GaugeRHS<D>gauge{};if(!qnf::Assemble(qnf::Gauge(Reference(p),u,gp,{.85,.95,sigma,true}),D(p.omega),gauge))throw std::runtime_error("gauge invalid");
 const auto b=hyp::PenroseMetric(u.metric,u.chi);const auto bg=hyp::Geometry(b);const D alpha=u.alpha.value;D g[4][4]{},inv[4][4]{},dg[4][4][4]{},bd[4][3][3]{};
 for(int i=0;i<3;++i)for(int j=0;j<3;++j){g[i+1][j+1]=b.g[i][j];inv[i+1][j+1]=bg.inverse[i][j]-u.beta.value[i]*u.beta.value[j]/(alpha*alpha);bd[0][i][j]=f.metric[i][j]/u.chi.value-u.metric.g[i][j]*f.chi/(u.chi.value*u.chi.value);for(int z=0;z<3;++z)bd[z+1][i][j]=b.dg[z][i][j];}
 g[0][0]=-alpha*alpha;inv[0][0]=-D(1)/(alpha*alpha);for(int i=0;i<3;++i){inv[0][i+1]=inv[i+1][0]=u.beta.value[i]/(alpha*alpha);for(int j=0;j<3;++j){g[0][i+1]+=b.g[i][j]*u.beta.value[j];g[0][0]+=b.g[i][j]*u.beta.value[i]*u.beta.value[j];}g[i+1][0]=g[0][i+1];}
 for(int z=0;z<4;++z){D da=z==0?gauge.alpha:u.alpha.d[z-1];dg[z][0][0]=-D(2)*alpha*da;for(int i=0;i<3;++i)for(int j=0;j<3;++j){D dbi=z==0?gauge.beta[i]:u.beta.d[z-1][i],dbj=z==0?gauge.beta[j]:u.beta.d[z-1][j];dg[z][i+1][j+1]=bd[z][i][j];dg[z][0][i+1]+=bd[z][i][j]*u.beta.value[j]+b.g[i][j]*dbj;dg[z][0][0]+=bd[z][i][j]*u.beta.value[i]*u.beta.value[j]+D(2)*b.g[i][j]*u.beta.value[j]*dbi;}for(int i=0;i<3;++i)dg[z][i+1][0]=dg[z][0][i+1];}
 D H[4][4]{},box{},N{};for(int aa=0;aa<4;++aa)for(int bb=0;bb<4;++bb){if(aa&&bb)H[aa][bb]=p.omega_hessian[aa-1][bb-1];for(int i=0;i<3;++i)for(int l=0;l<4;++l)H[aa][bb]-=D(.5*p.domega[i])*inv[i+1][l]*(dg[aa][l][bb]+dg[bb][l][aa]-dg[l][aa][bb]);box+=inv[aa][bb]*H[aa][bb];}for(int i=0;i<3;++i)for(int j=0;j<3;++j)N+=inv[i+1][j+1]*D(p.domega[i]*p.domega[j]);double shear=0;for(int aa=0;aa<4;++aa)for(int bb=0;bb<4;++bb)shear=std::max(shear,std::abs((H[aa][bb]-g[aa][bb]*box/D(4)).d/p.omega));return {box.d/p.omega,N.d/(p.omega*p.omega),shear,(-D(6)*box/D(p.omega)+D(12)*N/D(p.omega*p.omega)).d};}

int main(){std::cout<<std::setprecision(17)<<"{\"controls\":[";bool first=true;double Cmax=0,Rmax=0,geo=0,geoN=0,Boxerr=0,Shearmax=0,Curvmax=0;const double w[4]={4,-6,4,-1};for(double a:{.5,.75,1.,2.})for(double sigma:{3.,5.})for(int dir=0;dir<2;++dir){const std::array<double,3>n=dir?std::array<double,3>{.36,-.48,.8}:std::array<double,3>{1,0,0};hyp::LayerReference<double>ref(1,a,{true,.05,.95});auto p0=ref.At(n[0],n[1],n[2]);for(int col=0;col<120;++col){auto u0=Initial(p0,a,col);auto ic=Constraints(u0,p0);for(double z:ic)Cmax=std::max(Cmax,std::abs(z));auto ir=Parts(p0,u0,10,sigma,true);double R=0;for(auto z:ir.s)R=std::max(R,std::abs(z.d));Rmax=std::max(Rmax,R);auto om0=Omega(u0,p0);double N0boundary=Null(p0,u0),Q0boundary=u0.trace.value.d-3*om0.normal.d;
 double N1boundary=0;auto gg=hyp::Geometry(u0.metric);for(int z=0;z<3;++z){D dG{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){D di{};for(int t=0;t<3;++t)for(int v=0;v<3;++v)di-=gg.inverse[i][t]*u0.metric.dg[z][t][v]*gg.inverse[v][j];dG+=(u0.chi.d[z]*gg.inverse[i][j]+u0.chi.value*di)*D(p0.domega[i]*p0.domega[j])+u0.chi.value*gg.inverse[i][j]*D(p0.omega_hessian[z][i]*p0.domega[j]+p0.domega[i]*p0.omega_hessian[z][j]);}N1boundary-=a*n[z]*(dG-D(2)*om0.normal*om0.dnormal[z]).d;}
 double N1[3]{},N1g[3]{},N0t[3]{},N0[3]{},Nfirst[3]{};std::array<double,20>F0{};
 for(int lev=0;lev<3;++lev)for(int k=0;k<4;++k){double O=std::ldexp(.001,-lev)*(k+1),r=std::sqrt(1-2*a*O);auto p=ref.At(r*n[0],r*n[1],r*n[2]);auto u=Initial(p,a,col);auto F=RHS(p,u,sigma);double g=0;for(int z=0;z<20;++z)if(z!=0&&(z<4||z>6))g=std::max(g,std::abs(F[z]));geo=std::max(geo,g);auto c=Constraints(u,p);for(double z:c)Cmax=std::max(Cmax,std::abs(z));auto reg=FourRegularity(u,p,sigma);Boxerr=std::max(Boxerr,std::abs(reg[0]-sigma*reg[1]));Shearmax=std::max(Shearmax,reg[2]);Curvmax=std::max(Curvmax,std::abs(reg[3]));double nd=Ndot(p,u,F),ndg=Ndot(p,u,F,false);geoN=std::max(geoN,std::abs(nd-ndg));N1[lev]+=w[k]*nd/p.omega;N1g[lev]+=w[k]*ndg/p.omega;N0t[lev]+=w[k]*nd;double nv=Null(p,u);N0[lev]+=w[k]*nv;Nfirst[lev]+=w[k]*nv/p.omega;if(lev==2)for(int z=0;z<20;++z)F0[z]+=w[k]*F[z];}
 auto next=Lift(p0.state);for(int z:{0,4,5,6})Seed(next,z,J(D(0,F0[z])));Consistent(next);auto nr=Parts(p0,next,10,sigma,true);double nextR=0;for(auto z:nr.s)nextR=std::max(nextR,std::abs(z.d));if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"sigma\":"<<sigma<<",\"dir\":"<<dir<<",\"col\":"<<col<<",\"initial_R0_error\":"<<R<<",\"initial_N0_boundary\":"<<N0boundary<<",\"initial_N1_boundary\":"<<N1boundary<<",\"initial_Q0_boundary\":"<<Q0boundary<<",\"initial_N0\":["<<N0[0]<<','<<N0[1]<<','<<N0[2]<<"],\"initial_N1\":["<<Nfirst[0]<<','<<Nfirst[1]<<','<<Nfirst[2]<<"],\"N0_t\":["<<N0t[0]<<','<<N0t[1]<<','<<N0t[2]<<"],\"N1_t_actual\":["<<N1[0]<<','<<N1[1]<<','<<N1[2]<<"],\"N1_t_geometric_zero_oracle\":["<<N1g[0]<<','<<N1g[1]<<','<<N1g[2]<<"],\"next_R0_error\":"<<nextR<<",\"F0\":[";for(int z=0;z<20;++z)std::cout<<(z?",":"")<<F0[z];std::cout<<"]}";}}
 std::cout<<"],\"summary\":{\"initial_constraints_max\":"<<Cmax<<",\"initial_R0_max\":"<<Rmax<<",\"stationary_geometric_first_RHS_max\":"<<geo<<",\"Ndot_geometric_residual_max\":"<<geoN<<",\"initial_4D_Box_identity_max_error\":"<<Boxerr<<",\"initial_coordinate_shear_over_Omega_max\":"<<Shearmax<<",\"initial_coordinate_curvature_max\":"<<Curvmax<<"}}\n";}
